#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

static int find_first(const int *a,int n,int target){
    for(int i=0;i<n;++i) if(a[i]==target) return i;
    return -1;
}
int main(void) {
int a[256]; int n;
if (scanf("%d", &n)!=1 || n<0 || n>256) return 1;
for(int i=0;i<n;++i) if(scanf("%d", &a[i])!=1) return 1;
int target;if(scanf("%d",&target)!=1)return 1;printf("%d\n",find_first(a,n,target));
return 0;
}
